email.tenant_id = #{tenantId} AND 


        AND email.biz_type IN #{businessType}

    AND 1 = 0

mapper.select:
SELECT email.email_id, email.direction, email.subject, email.content_summary, email.from_address, email.to_addresses,
    email.cc_addresses, email.biz_type, email.biz_id, email.customer_id, email.contact_id, email.sender_user_id,
    email.message_record_id, email.send_time, email.send_status, email.attachment_count, email.read_flag, email.read_time,
    email.remark, email.create_time, email.create_by, customer.dept_id AS scope_dept_id, customer.owner_id AS scope_owner_id

WHERE 
AND email.customer_id = #{query.customerId}
AND email.biz_type = #{query.bizType}
AND email.biz_id = #{query.bizId}
AND email.direction = #{query.direction}
AND email.send_status = #{query.sendStatus}
AND email.subject LIKE CONCAT('%', #{query.subject}, '%')
ORDER BY email.create_time DESC, email.email_id DESC
